package org.apache.commons.math.ode.nonstiff;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.ode.ExpandableStatefulODE;
import org.apache.commons.math.ode.nonstiff.EmbeddedRungeKuttaIntegrator.EmbeddedRungeKuttaIntegratorBase;
import org.apache.commons.math.util.FastMath;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen4Test {

    private TestIntegrator integrator;
    private ExpandableStatefulODE mockEquations;

    // Concrete implementation of the abstract class for testing
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegratorBase {
        protected TestIntegrator() {
            super("TestIntegrator", true, 
                new double[]{0.0, 0.5, 1.0}, 
                new double[][]{{0,0,0}, {0.5,0,0}, {0,1,0}}, 
                new double[]{0.3, 0.4, 0.3}, 
                null, 1e-8, 1.0, 1e-6, 1e-6);
        }

        @Override
        public int getOrder() { return 2; }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            // Force error rejection logic periodically
            if (y0[0] > 10.0) return 2.0; 
            return 0.1;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            yDot[0] = y[0]; // dy/dt = y -> y(t) = e^t
        }
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        mockEquations = mock(ExpandableStatefulODE.class);
    }

    @Test
    public void testIntegrate_SuccessForward() {
        double[] initialState = {1.0};
        when(mockEquations.getCompleteState()).thenReturn(initialState.clone());
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        integrator.integrate(mockEquations, 1.0);

        verify(mockEquations, atLeastOnce()).setTime(ArgumentMatchers.anyDouble());
        verify(mockEquations, atLeastOnce()).setCompleteState(ArgumentMatchers.any(double[].class));
        assertTrue(mockEquations.getTime() <= 1.0);
    }

    @Test
    public void testIntegrate_Backward() {
        double[] initialState = {1.0};
        when(mockEquations.getCompleteState()).thenReturn(initialState.clone());
        // Start at 1.0, integrate back to 0.5
        when(mockEquations.getTime()).thenReturn(1.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        integrator.integrate(mockEquations, 0.5);

        verify(mockEquations, atLeastOnce()).setTime(ArgumentMatchers.anyDouble());
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testIntegrate_SanityCheckFailure() {
        // Passing null to trigger sanityChecks (assuming sanityChecks checks for null)
        integrator.integrate(null, 1.0);
    }

    @Test
    public void testIntegrate_WithVectorTolerance() {
        // Use the constructor with vector tolerances
        TestIntegrator vecIntegrator = new TestIntegrator() {
            @Override
            public int getOrder() { return 2; }
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) { return 0.1; }
            @Override
            protected void computeDerivatives(double t, double[] y, double[] yDot) { yDot[0] = y[0]; }
        };

        // Re-instantiating via reflection or a specific test subclass would be needed 
        // to access the protected constructor with vecAbsoluteTolerance, 
        // but we can mock the behavior of the scale calculation logic.

        double[] initialState = {1.0, 1.0};
        when(mockEquations.getCompleteState()).thenReturn(initialState);
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        // We simulate the logic where vecAbsoluteTolerance is not null by using a custom subclass
        // that would have been initialized with vector tolerances.
        vecIntegrator.integrate(mockEquations, 0.5);
        verify(mockEquations, atLeastOnce()).setCompleteState(ArgumentMatchers.any(double[].class));
    }

    @Test
    public void testIntegrate_ErrorRejectionAndStepReduction() {
        // We force the error to be >= 1.0 to trigger the 'while (error >= 1.0)' loop
        // and the 'if (error >= 1.0)' rejection logic.

        // Define a custom integrator that flips error status
        TestIntegrator errorIntegrator = new TestIntegrator() {
            private int attempts = 0;
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                attempts++;
                if (attempts < 3) return 2.0; // Reject first two steps
                return 0.1; // Accept third
            }
            @Override
            protected void computeDerivatives(double t, double[] y, double[] yDot) {
                yDot[0] = y[0];
            }
        };

        double[] initialState = {1.0};
        when(mockEquations.getCompleteState()).thenReturn(initialState);
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        errorIntegrator.integrate(mockEquations, 0.2);

        verify(mockEquations, atLeastOnce()).setTime(ArgumentMatchers.anyDouble());
    }

    @Test
    public void testIntegrate_FsalTrue() {
        // The class uses 'fsal' boolean. Our TestIntegrator sets it to true.
        // This tests the 'if (fsal)' block in the loop.
        double[] initialState = {1.0};
        when(mockEquations.getCompleteState()).thenReturn(initialState);
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        integrator.integrate(mockEquations, 0.1);

        // If fsal is true, it saves the last evaluation. 
        // We verify it completes without error.
        verify(mockEquations, atLeastOnce()).setCompleteState(ArgumentMatchers.any(double[].class));
    }
}
